# Surah Al-Baqarah (chapter 2) — part 29 (final): ayat 281-286 (IDs 288-293)
SURAH = 2

ENTRIES = {
288: (
"اور ڈرو اس دن سے جس دن تم اللہ کی طرف لوٹ کر آؤ گے — پھر ہر نفس کو اس کا کمایا ہوا پورا پورا دیا جائے گا اور ان پر ظلم نہیں کیا جائے گا۔",
"""۱۔ قیامت کے دن کی یاد دہانی کی آخری تلقین — سورہ کے اختتام کی طرف لے جانے والی تنبیہ۔
۲۔ ’’وَاتَّقُوا يَوْمًا تُرْجَعُونَ فِيهِ إِلَى اللّٰہِ‘‘ — اور ڈرو اس دن سے جس دن تم اللہ کی طرف لوٹ کر آؤ گے — یعنی قیامت کا خوف دل میں رکھو۔
۳۔ ’’ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ‘‘ — پھر ہر نفس کو اس کا کمایا ہوا پورا پورا دیا جائے گا — یعنی ہر عمل کا بدلہ ملے گا۔
۴۔ ’’وَهُمْ لَا يُظْلَمُونَ‘‘ — اور ان پر ظلم نہیں کیا جائے گا — یعنی کوئی حق ضائع نہیں ہوگا۔
۵۔ عملی سبق: ہر لمحہ قیامت کی عدالت یاد رکھو؛ ظلم سے بچو — اللہ ہر معاملے کا حتمی فیصلہ کرنے والا ہے۔"""
),
289: (
"اے ایمان والو! جب تم کسی مقررہ مدت کے لیے آپس میں قرض کا معاملہ کرو تو اسے لکھ لو — اور تم میں سے ایک کاتب انصاف کے ساتھ لکھے — اور کاتب ہر گز اس سے انکار نہ کرے جو اسے اللہ نے سکھایا ہے — پس اسے لکھنا چاہیے اور اسے لکھنا چاہیے جس کے اوپر حق ہے — اور اسے اپنے رب اللہ سے ڈرتے رہنا چاہیے — اور اس میں سے کچھ بھی کم نہ کرے — پھر اگر وہ جس کے اوپر حق ہے احمق ہے یا کمزور ہے یا خود املا نہ کر سکتا ہو تو اس کا ولی انصاف کے ساتھ املا کرے — اور اپنے مردوں میں سے دو گواہ مقرر کرو — پھر اگر دو مرد نہ ہوں تو ایک مرد اور دو عورتیں — ان (لوگوں) میں سے جن پر تم راضی ہو — تاکہ اگر ایک عورت بھول جائے تو دوسری اسے یاد دہانی کرا دے — اور گواہ ہرگز اس وقت انکار نہ کریں جب انہیں بلایا جائے — اور اس (قرض کے معاہدے) کو لکھنے سے بور مت ہو — چھوٹا ہو یا بڑا — اس کی مدت تک — یہ اللہ کے نزدیک زیادہ انصاف والا ہے اور شہادت کے لیے مضبوط تر ہے اور شکوک سے بچنے کے زیادہ قریب ہے — سوائے اس صورت میں کہ (معاملہ) موجودہ تجارت کا ہو جو تم آپس میں چلاتے ہو — پھر تم پر کوئی گناہ نہیں کہ اسے نہ لکھو — اور خرید و فروخت کے وقت گواہ بناؤ — اور نہ کاتب کو تکلیف دو اور نہ گواہ کو — اور اگر تم ایسا کرو گے تو تمہیں نافرمانی ہوگی — اور اللہ سے ڈرو — اور اللہ تمہیں سکھاتا ہے — اور اللہ ہر چیز کو جانتا ہے۔",
"""۱۔ یہ آیت قرآن کی سب سے طویل آیت ہے — دین کا مالی و قانونی نظام کا مکمل دستور۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰ أَجَلٍ مُّسَمًّى فَاكْتُبُوهُ‘‘ — اے ایمان والو! جب تم کسی مقررہ مدت کے لیے آپس میں قرض کا معاملہ کرو تو اسے لکھ لو — یعنی ہر قرض معاملہ تحریری شکل میں ہونا چاہیے۔
۳۔ ’’وَلْيَكْتُب بَّيْنَكُمْ كَاتِبٌ بِالْعَدْلِ‘‘ — اور تم میں سے ایک کاتب انصاف کے ساتھ لکھے — یعنی غیر جانبدار اور معتبر لکھنے والا ہو۔
۴۔ ’’وَلَا يَأْبَ كَاتِبٌ أَن يَكْتُبَ كَمَا عَلَّمَهُ اللّٰہُ فَلْيَكْتُبْ‘‘ — اور کاتب ہر گز اس سے انکار نہ کرے جو اسے اللہ نے سکھایا ہے — پس اسے لکھنا چاہیے — لکھنے والے کی ذمہ داری ہے کہ وہ انصاف سے لکھے۔
۵۔ ’’وَلْيُمْلِلِ الَّذِي عَلَيْهِ الْحَقُّ وَلْيَتَّقِ اللّٰہَ رَبَّهُ وَلَا يَبْخَسْ مِنْهُ شَيْئًا‘‘ — اور اسے لکھنا چاہیے جس کے اوپر حق ہے — اور اسے اپنے رب اللہ سے ڈرتے رہنا چاہیے — اور اس میں سے کچھ بھی کم نہ کرے — یعنی مدیون خود املا کرے اور پورا لکھوائے۔
۶۔ ’’فَإِن كَانَ الَّذِي عَلَيْهِ الْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أَن يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُ بِالْعَدْلِ‘‘ — پھر اگر وہ جس کے اوپر حق ہے احمق ہے یا کمزور ہے یا خود املا نہ کر سکتا ہو تو اس کا ولی انصاف کے ساتھ املا کرے — یعنی کمزور افراد کی جگہ ان کے ولی لکھوائیں۔
۷۔ ’’وَاسْتَشْهِدُوا شَهِيدَيْنِ مِن رِّجَالِكُمْ‘‘ — اور اپنے مردوں میں سے دو گواہ مقرر کرو — یعنی دو گواہ ضروری ہیں۔
۸۔ ’’فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَامْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ الشُّهَدَاءِ أَن تَضِلَّ إِحْدَاهُمَا فَتُذَكِّرَ إِحْدَاهُمَا الْأُخْرَىٰ‘‘ — پھر اگر دو مرد نہ ہوں تو ایک مرد اور دو عورتیں — ان (لوگوں) میں سے جن پر تم راضی ہو — تاکہ اگر ایک عورت بھول جائے تو دوسری اسے یاد دہانی کرا دے — یعنی شرعی گواہی میں احتیاط کے اصول واضح ہیں۔
۹۔ ’’وَلَا يَأْبَ الشُّهَدَاءُ إِذَا مَا دُعُوا‘‘ — اور گواہ ہرگز اس وقت انکار نہ کریں جب انہیں بلایا جائے — گواہی دینا فرض ہے۔
۱۰۔ ’’وَلَا تَسْأَمُوا أَن تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَىٰ أَجَلِهِ‘‘ — اور اس (قرض کے معاہدے) کو لکھنے سے بور مت ہو — چھوٹا ہو یا بڑا — اس کی مدت تک — یعنی چھوٹا معاملہ بھی لکھنا چاہیے۔
۱۱۔ ’’ذَٰلِكُمْ أَقْسَطُ عِندَ اللّٰہِ وَأَقْوَمُ لِلشَّهَادَۃِ وَأَدْنَىٰ أَلَّا تَرْتَابُوا‘‘ — یہ اللہ کے نزدیک زیادہ انصاف والا ہے اور شہادت کے لیے مضبوط تر ہے اور شکوک سے بچنے کے زیادہ قریب ہے — یعنی قانونی حفاظت۔
۱۲۔ ’’إِلَّا أَن تَكُونَ تِجَارَۃً حَاضِرَۃً تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا‘‘ — سوائے اس صورت میں کہ (معاملہ) موجودہ تجارت کا ہو جو تم آپس میں چلاتے ہو — پھر تم پر کوئی گناہ نہیں کہ اسے نہ لکھو — یعنی نقد معاملے میں تحریر کی ضرورت نہیں۔
۱۳۔ ’’وَأَشْهِدُوا إِذَا تَبَايَعْتُمْ‘‘ — اور خرید و فروخت کے وقت گواہ بناؤ۔
۱۴۔ ’’وَلَا يُضَارَّ كَاتِبٌ وَلَا شَهِيدٌ‘‘ — اور نہ کاتب کو تکلیف دو اور نہ گواہ کو — یعنی لکھنے والے اور گواہوں کو تنگ نہ کرو۔
۱۵۔ ’’وَإِن تَفْعَلُوا فَإِنَّهُ فُسُوقٌ بِكُمْ‘‘ — اور اگر تم ایسا کرو گے تو تمہیں نافرمانی ہوگی۔
۱۶۔ ’’وَاتَّقُوا اللّٰہَ وَيُعَلِّمُكُمُ اللّٰہُ وَاللّٰہُ بِكُلِّ شَيْءٍ عَلِيمٌ‘‘ — اور اللہ سے ڈرو — اور اللہ تمہیں سکھاتا ہے — اور اللہ ہر چیز کو جانتا ہے۔
۱۷۔ عملی سبق: ہر قرض اور ہر معاہدہ تحریری شکل میں کرو؛ گواہ مقرر کرو — یہی تمہاری حفاظت ہے۔"""
),
290: (
"اور اگر تم سفر میں ہو اور تمہیں کوئی کاتب نہ ملے تو (رہن رکھو) دستی قبضہ شدہ (چیز) — پھر اگر تم میں سے بعض بعض پر بھروسہ کریں تو وہ جس پر بھروسہ کیا گیا ہے امانت ادا کرے اور اپنے رب اللہ سے ڈرے — اور گواہی کو مت چھپاؤ — اور جو اسے چھپائے تو بے شک اس کا دل گنہگار ہے — اور اللہ تمہارے اعمال جانتا ہے۔",
"""۱۔ سفر میں قرض لین دین کی صورت — رہن (گروی) کا اصول۔
۲۔ ’’وَإِن كُنتُمْ عَلَىٰ سَفَرٍ وَلَمْ تَجِدُوا كَاتِبًا فَرِهَانٌ مَّقْبُوضَۃٌ‘‘ — اور اگر تم سفر میں ہو اور تمہیں کوئی کاتب نہ ملے تو (رہن رکھو) دستی قبضہ شدہ (چیز) — یعنی سفر میں تحریر ممکن نہ ہو تو گروی رکھو۔
۳۔ ’’فَإِنْ أَمِنَ بَعْضُكُم بَعْضًا فَلْيُؤَدِّ الَّذِي اؤْتُمِنَ أَمَانَتَهُ‘‘ — پھر اگر تم میں سے بعض بعض پر بھروسہ کریں تو وہ جس پر بھروسہ کیا گیا ہے امانت ادا کرے — یعنی باہمی اعتماد کی صورت میں رہن کی ضرورت نہیں، امانت ادا کرنی ہے۔
۴۔ ’’وَلْيَتَّقِ اللّٰہَ رَبَّهُ‘‘ — اور اپنے رب اللہ سے ڈرے — یعنی اللہ کا خوف رکھنا لازم ہے۔
۵۔ ’’وَلَا تَكْتُمُوا الشَّهَادَۃَ وَمَن يَكْتُمْهَا فَإِنَّهُ آثِمٌ قَلْبُهُ‘‘ — اور گواہی کو مت چھپاؤ — اور جو اسے چھپائے تو بے شک اس کا دل گنہگار ہے — یعنی گواہی چھپانا سنگین گناہ ہے۔
۶۔ ’’وَاللّٰہُ بِمَا تَعْمَلُونَ عَلِيمٌ‘‘ — اور اللہ تمہارے اعمال جانتا ہے۔
۷۔ عملی سبق: سفر میں بھی امانت کی حفاظت کرو؛ گواہی نہ چھپاؤ — دل کو گنہگار سے بچاؤ۔"""
),
291: (
"اللہ ہی کے لیے ہے جو کچھ آسمانوں میں ہے اور زمین میں — اور اگر تم ظاہر کرو جو تمہارے دلوں میں ہے یا اسے چھپاؤ — اللہ تم سے اس کے بارے میں محاسبہ کرے گا — پھر جس کے لیے وہ چاہے بخشے اور جسے چاہے عذاب کرے — اور اللہ ہر چیز پر قادر ہے۔",
"""۱۔ اللہ کا احاطہ کامل ہے — نیت بھی اسی کے علم میں ہے۔
۲۔ ’’لِّلّٰہِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ‘‘ — اللہ ہی کے لیے ہے جو کچھ آسمانوں میں ہے اور زمین میں — یعنی ساری کائنات اللہ کی ملکیت ہے۔
۳۔ ’’وَإِن تُبْدُوا مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ اللّٰہُ‘‘ — اور اگر تم ظاہر کرو جو تمہارے دلوں میں ہے یا اسے چھپاؤ — اللہ تم سے اس کے بارے میں محاسبہ کرے گا — یعنی نیت اور ارادے دونوں کا اللہ کے سامنے حساب ہوگا۔
۴۔ ’’فَيَغْفِرُ لِمَن يَشَاءُ وَيُعَذِّبُ مَن يَشَاءُ‘‘ — پھر جس کے لیے وہ چاہے بخشے اور جسے چاہے عذاب کرے — یعنی اللہ کا حکم مکمل اور آزاد ہے۔
۵۔ ’’وَاللّٰہُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ‘‘ — اور اللہ ہر چیز پر قادر ہے۔
۶۔ عملی سبق: دل میں بھی اچھی نیت اور اللہ کا خوف رکھو — اللہ سب جانتا ہے۔"""
),
292: (
"پیغمبر ایمان لائے اس پر جو ان کے رب کی طرف سے نازل ہوا اور مؤمنین — سب اللہ پر، اس کے فرشتوں پر، اس کی کتابوں پر اور اس کے پیغمبروں پر ایمان لائے — ہم ان کے پیغمبروں میں سے کسی میں فرق نہیں کرتے — اور انہوں نے کہا: ہم نے سنا اور اطاعت کی — اے ہمارے رب! تیری مغفرت (چاہتے ہیں) اور تیری طرف لوٹنا ہے۔",
"""۱۔ رسول ﷺ اور مؤمنین کا ایمان کا عظیم اقرار — اسلام کی سب سے جامع دعا/کلمہ۔
۲۔ ’’آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ‘‘ — پیغمبر ایمان لائے اس پر جو ان کے رب کی طرف سے نازل ہوا اور مؤمنین — یعنی نبی اور امت دونوں ایمان میں شریک ہیں۔
۳۔ ’’كُلٌّ آمَنَ بِاللّٰہِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ‘‘ — سب اللہ پر، اس کے فرشتوں پر، اس کی کتابوں پر اور اس کے پیغمبروں پر ایمان لائے — یعنی ایمانِ کامل چھ اجزاء پر مشتمل ہے۔
۴۔ ’’لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ‘‘ — ہم ان کے پیغمبروں میں سے کسی میں فرق نہیں کرتے — یعنی ہم کسی نبی کا انکار نہیں کرتے۔
۵۔ ’’وَقَالُوا سَمِعْنَا وَأَطَعْنَا‘‘ — اور انہوں نے کہا: ہم نے سنا اور اطاعت کی — یعنی ایمان کے بعد حکم بجا لانا۔
۶۔ ’’غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ‘‘ — اے ہمارے رب! تیری مغفرت (چاہتے ہیں) اور تیری طرف لوٹنا ہے — یعنی اللہ کی بخشش کی التجا اور لوٹنا اُسی کی طرف۔
۷۔ عملی سبق: روزانہ رات کو یہ کلمہ (آمَنَ الرَّسُولُ) پڑھیں؛ یہ ایمان کی جامع حفاظت ہے۔"""
),
293: (
"اللہ کسی نفس کو اس کی وسعت سے زیادہ مکلف نہیں کرتا — اس کے لیے ہے جو اس نے کمایا اور اس پر ہے جو اس نے کمایا — اے ہمارے رب! اگر ہم بھول جائیں یا غلط ہو جائیں تو ہمیں نہ پکڑ — اے ہمارے رب! اور ہم پر بوجھ نہ رکھ جیسا کہ تو نے ہم سے پہلے والوں پر رکھا — اے ہمارے رب! اور ہم پر وہ بوجھ نہ ڈال جس کی ہم طاقت نہیں رکھتے — اور ہمیں ہمارے گناہوں سے صاف کر دے اور ہمیں بخش دے اور ہم پر رحم کر — تو ہمارا مولا ہے — پس ہمیں کافروں کے گروہ پر نصرت دے۔",
"""۱۔ یہ آیت قرآن کی آخری آیت سورہ بقرہ کی — اور سب سے جامع دعائیں۔
۲۔ ’’لَا يُكَلِّفُ اللّٰہُ نَفْسًا إِلَّا وُسْعَهَا‘‘ — اللہ کسی نفس کو اس کی وسعت سے زیادہ مکلف نہیں کرتا — یعنی اللہ کبھی اپنی طاقت سے زیادہ ذمہ داری نہیں ڈالتا۔
۳۔ ’’لَّهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ‘‘ — اس کے لیے ہے جو اس نے کمایا اور اس پر ہے جو اس نے کمایا — یعنی ہر عمل کا پھل خود اسی کو ملے گا۔
۴۔ ’’رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا‘‘ — اے ہمارے رب! اگر ہم بھول جائیں یا غلط ہو جائیں تو ہمیں نہ پکڑ — یعنی بھولنے اور غلطی پر بھی اللہ سے معافی مانگنا چاہیے۔
۵۔ ’’رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا‘‘ — اے ہمارے رب! اور ہم پر بوجھ نہ رکھ جیسا کہ تو نے ہم سے پہلے والوں پر رکھا — یعنی پہلی امتوں جیسی سخت شریعت نہیں، آسانی والی شریعت دے۔
۶۔ ’’رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَۃَ لَنَا بِهِ‘‘ — اے ہمارے رب! اور ہم پر وہ بوجھ نہ ڈال جس کی ہم طاقت نہیں رکھتے — یعنی ہر قسم کا غیر ضروری بوجھ ہٹادے۔
۷۔ ’’وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا‘‘ — اور ہمیں ہمارے گناہوں سے صاف کر دے اور ہمیں بخش دے اور ہم پر رحم کر۔
۸۔ ’’أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ‘‘ — تو ہمارا مولا ہے — پس ہمیں کافروں کے گروہ پر نصرت دے۔
۹۔ عملی سبق: ہر نماز کے بعد یہ دعا پڑھیں؛ یہ قرآن کی سفارت اور تمام امیدوں کا کلمہ ہے۔"""
),
}
